  for (const code of Object.keys(DISPLAY_STRINGS)) Object.assign(T[code], DISPLAY_STRINGS[code]);

  let current = 'en';
  const staticText = [];
  const staticAttrs = [];

  function interpolate(text, vars) {
    if (!vars) return text;
    return text.replace(/\{([a-zA-Z0-9_]+)\}/g, (_, key) => Object.prototype.hasOwnProperty.call(vars, key) ? String(vars[key]) : `{${key}}`);
  }

  function t(source, vars) {
    const translated = current === 'en' ? source : (T[current]?.[source] ?? source);
    return interpolate(translated, vars);
  }

  function captureStaticDom(root = document.body) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      const parent = node.parentElement;
      if (!parent || ['SCRIPT','STYLE','TEXTAREA'].includes(parent.tagName)) continue;
      if (!node.nodeValue.trim()) continue;
      staticText.push({ node, source: node.nodeValue });
    }
    for (const element of root.querySelectorAll('[title],[placeholder],[aria-label]')) {
      for (const attr of ['title','placeholder','aria-label']) {
        if (element.hasAttribute(attr)) staticAttrs.push({ element, attr, source: element.getAttribute(attr) });
      }
    }
  }

  function translateStaticDom() {
    for (const item of staticText) {
      if (!item.node.isConnected) continue;
      const leading = item.source.match(/^\s*/)?.[0] || '';
      const trailing = item.source.match(/\s*$/)?.[0] || '';
      const core = item.source.trim();
      item.node.nodeValue = `${leading}${t(core)}${trailing}`;
    }
    for (const item of staticAttrs) {
      if (item.element.isConnected) item.element.setAttribute(item.attr, t(item.source));
    }
  }

  function setLanguage(language) {
    current = Object.prototype.hasOwnProperty.call(languages, language) ? language : 'en';
    document.documentElement.lang = current;
    translateStaticDom();
  }

  function locale() { return languages[current]?.locale || 'en-US'; }
  function language() { return current; }

  captureStaticDom();
  window.DiskMosaicI18n = Object.freeze({ languages, t, setLanguage, locale, language, translateStaticDom });
